// The layout: the avenues, the blocks between them, and what stands on each block.
//
// Records only — no meshes, no simulation. world.js turns these into geometry, and the player, the
// crowd and the police ask them whether a point is solid. Keeping it data-only is what lets a
// screenshot stage the town and a test walk through it with no renderer attached.
//
// Grid: avenues at x = k*264 and z = k*264 for k = 0..6, each 48 m kerb to kerb. Between two
// avenues is a 216 m block; every block starts 12 m in from the kerb, so it wears a pavement ring
// with a lot or two of buildings inside it, or a park.

import { GRID, TOWN, PALETTE } from './settings.js';
import { rngFrom } from './random.js';

export const PITCH = GRID.block;
export const HALF_ROAD = GRID.road / 2;
export const SETBACK = GRID.inset;
export const LAST_LINE = (GRID.cols - 1) * PITCH;

// West of town: promenade, then sand, then water. South of town: quay, then bay.
export const COAST = {
  kerb: -HALF_ROAD,
  promenade: -104,
  sand: -300,
  shore: -336,
  quay: LAST_LINE + HALF_ROAD,
  bay: LAST_LINE + HALF_ROAD + 26,
};

export const BOUNDS = {
  roadMin: -HALF_ROAD,
  roadMax: LAST_LINE + HALF_ROAD,
  x0: COAST.shore,
  x1: LAST_LINE + HALF_ROAD,
  z0: TOWN.min,
  z1: COAST.bay + 40,
};

const LINES = [];
for (let i = 0; i < GRID.cols; i += 1) LINES.push(i * PITCH);

/** The centre line of every avenue, shared by both axes. */
export function avenues() {
  return LINES;
}

const NEIGHBOURHOODS = [
  { name: 'Gulf Promenade', near: (x) => x < 20 },
  { name: 'Neon Heights', near: (x, z) => x > 560 && x < 1120 && z > 380 && z < 1120 },
  { name: 'Coral Marina', near: (x, z) => z > 1340 },
  { name: 'Osprey Harbor', near: (x, z) => x > 1300 && z < 1360 },
  { name: 'Riviera Palms', near: (x, z) => x < 560 && z < 980 },
  { name: 'Sunglass Strip', near: (x, z) => z < 360 },
