/** Pale beach sand with shell grit and wind ripples. */
export function sandTexture() {
  return once('sand', () => {
    const c = sheet(256, 256);
    const g = c.getContext('2d');
    const r = rngFrom(9);
    g.fillStyle = PALETTE.sand;
