      g.save();
      g.translate(128, 128);
      g.rotate(a);
      const grad = g.createLinearGradient(0, 0, len, 0);
      grad.addColorStop(0, '#1f5a37');
      grad.addColorStop(1, '#57a35e');
      g.fillStyle = grad;
      g.beginPath();
      g.moveTo(0, -5);
      g.quadraticCurveTo(len * 0.55, -22 * droop, len, 4);
