// The simulation: one object holding the player, the traffic, the crowd, the police and the job
// chain, and one tick that advances all of them in the right order.
//
// The live game, a paused frame and a staged screenshot all come through here. tick takes the input
// as plain data, so a screenshot can hand the world a script and land in a known pose; it knows
// nothing about meshes, cameras or pixels.
//
// The order matters and is deliberate:
//   1. the player's own clocks and reload
//   2. the player's movement (on foot or driving) and their trigger
//   3. traffic (which needs the player as an obstacle), then the crowd, then the police
//   4. the player's rounds, resolved against walls, people and officers
//   5. the police's rounds, resolved against the player
//   6. the job chain, and the arrest or death check that can end the run

import { GUN } from './settings.js';
import { CityLayout } from './layout.js';
import { rngFrom } from './random.js';
import { seedTraffic, driveTraffic, carInLane } from './traffic.js';
import { seedCrowd, walkCrowd, scatterCrowd, personAt, fellAt, bodyAhead, newPerson } from './crowd.js';
import { newPolice, runPolice, raiseHeat, standDown, hitOfficer, arrestAt } from './police.js';
import { newStory, currentJob, testJob, announce, liveCondition, JOBS } from './missions.js';
import {
  newPlayer,
  toggleVehicle,
  nearestCar,
  fireWeapon,
  reloadWeapon,
  hurt,
  advanceRound,
  walkPlayer,
  drivePlayer,
  HOME,
} from './player.js';

export const STEP = 1 / 60;

/** Build a world for a seed: layout, cast, story, and the dressing the first two jobs need. */
export function createSim(seed = 1) {
  const sim = {
    seed,
    layout: new CityLayout(seed),
    rand: rngFrom(seed * 3 + 9),
    time: 0,
    mode: 'title', // title | play | paused | busted | wasted | complete
    player: newPlayer(),
    traffic: seedTraffic(seed),
    crowd: seedCrowd(seed),
    police: newPolice(seed),
    story: newStory(),
    rounds: [],
    impacts: [],
    floaters: [],
    prompt: '',
    shake: 0,
    flash: 0,
    crewDown: 0,
    pointer: { x: 0, y: 0 },
    project: null,
    viewYaw: 0,
    endReason: '',
    events: { onShot: null, onCopShot: null, onCash: null, onReload: null, onImpact: null, onSave: null },
    onCrime: null,
  };
  sim.onCrime = (kind, at) => commitCrime(sim, kind, at);
  dressForJob(sim);
  return sim;
}

// ---------------------------------------------------------------- the job's props

/**
 * The world changes as the chain moves: job 2 parks a pink drop-top on Sunglass Strip for the
 * player to take, and job 3 puts a crew of three on the marina forecourt. Both are placed from the
 * job's own record, so the marker and the thing inside it never disagree.
 */
function dressForJob(sim) {
  const job = currentJob(sim.story);
  if (!job) return;

  if (job.car) {
    const car = carInLane(job.car.kind, sim.layout.closestAvenue(job.car.z), job.car.x, { dx: 0, dz: -1 }, job.car.paint, {
      parked: true,
      occupied: false,
      missionCar: job.id,
    });
    car.x = job.car.x;
    car.z = job.car.z;
    sim.traffic.push(car);
  }

  if (job.beat === 'clear') {
    for (let i = 0; i < job.need; i += 1) {
      const a = (i / job.need) * Math.PI * 2 + 0.4;
      const p = newPerson(sim.rand, job.at.x + Math.cos(a) * (job.radius * 0.42), job.at.z + Math.sin(a) * (job.radius * 0.42), a + Math.PI);
      p.crew = true;
      p.shirt = '#2b2b36';
      p.trousers = '#16161d';
      sim.crowd.push(p);
    }
  }
}

/** How many of the crew are down inside the marker, for a `clear` job. */
function countCrewDown(sim, job) {
  if (job.beat !== 'clear') return 0;
  let n = 0;
  for (const p of sim.crowd) {
    if (p.down > 0 && Math.hypot(p.x - job.at.x, p.z - job.at.z) < job.radius + 4) n += 1;
  }
  return n;
}

// ---------------------------------------------------------------- crime

/**
 * Something the law cares about. A shot fired is a star; a shot that drops somebody is three; a
 * stolen car is one or two depending on whether anyone saw it happen.
 */
function commitCrime(sim, kind, at) {
  if (sim.mode !== 'play') return;
  if (kind === 'shot') {
    raiseHeat(sim.police, 1);
    scatterCrowd(sim.crowd, at.x, at.z, 52, () => {
      // A witness who can see the shot calls it in harder.
      for (const p of sim.crowd) {
        if (p.down > 0) continue;
        if (Math.hypot(p.x - at.x, p.z - at.z) < 22) {
          raiseHeat(sim.police, 2);
          break;
        }
      }
    });
    return;
  }
  if (kind === 'kill') {
    raiseHeat(sim.police, 3);
    return;
  }
  if (kind === 'theft') {
    const seen = sim.police.units.some((u) => Math.hypot(u.x - at.x, u.z - at.z) < 60);
    raiseHeat(sim.police, seen ? 2 : 1);
    return;
  }
  if (kind === 'copdown') {
    raiseHeat(sim.police, 4);
  }
}

// ---------------------------------------------------------------- the frame

/**
 * Advance the world one step. `input` is
 *   { move: {x, z}, aim: {x, z} | null, fire, use, run, reload }
 * where `move` is world-space (the camera maps WASD onto the ground), `aim` is a ground point to
 * face, `use` is true on the frame E came down, and `fire` is held.
 */
export function tick(sim, dt, input) {
  sim.time += dt;
  const p = sim.player;

  sim.shake *= Math.exp(-dt * 6);
  sim.flash = Math.max(0, sim.flash - dt * 2.4);
  p.muzzle = Math.max(0, p.muzzle - dt * 9);
  p.recoil = Math.max(0, p.recoil - dt * 4);
  p.hurt = Math.max(0, p.hurt - dt * 0.9);
  p.cool = Math.max(0, p.cool - dt);
  tickReload(sim, dt);

  if (sim.mode === 'play') {
    if (input.use) toggleVehicle(sim);
    if (p.driving) drivePlayer(sim, dt, input);
    else walkPlayer(sim, dt, input);
    if (input.fire) fireWeapon(sim);
    if (input.reload) reloadWeapon(sim);
  }

  stepWorld(sim, dt);

  if (sim.mode === 'play') {
    if (p.hp <= 0) {
      sim.mode = 'wasted';
      sim.endReason = 'wasted';
      sim.shake = 1.2;
      sim.story.toastT = 0;
      sim.story.toast = '';
    } else if (!p.driving && arrestAt(sim.police, p.x, p.z)) {
      sim.mode = 'busted';
      sim.endReason = 'busted';
      sim.police.busted += 1;
      standDown(sim.police);
      sim.story.toastT = 0;
      sim.story.toast = '';
    }
  }
  updatePrompt(sim);
}

// The reload clock is the only part of the weapon the sim runs itself, because a reload can finish
// while the world is paused on a card.
function tickReload(sim, dt) {
  const p = sim.player;
  if (p.reload <= 0) return;
  p.reload -= dt;
  if (p.reload > 0) return;
  const take = Math.min(GUN.clip - p.clip, p.ammo);
  p.clip += take;
  p.ammo -= take;
  if (take > 0) sim.events.onReload?.();
}

/** Traffic, crowd, police, bullets and the job: everything that runs while the world is live. */
function stepWorld(sim, dt) {
  const p = sim.player;
  const live = sim.mode === 'play' || sim.mode === 'busted' || sim.mode === 'wasted';
