    // ---- the throttle: hold the cruise, or fall away with the gap to what is in front.
    const want = gap < 5 ? 0 : gap < 26 ? car.cruise * (0.18 + 0.032 * gap) : car.cruise;
    const rate = want < car.speed ? 5.2 : 1.15;
